-- feed_social_visibility (09-03, SOCIAL-03, SOCIAL-04, SOCIAL-06; D-473, D-483, D-484) - the stamped
-- audience of a feed post and the two restrictive policies that gate it. GENERATED by drizzle-kit
-- from `packages/modules/feed/db/schema.ts`; only this header is hand-written. EXPAND-ONLY: two new
-- columns and two checks, nothing existing is removed or altered.
--
-- D-473: `visibility` is `'tenant'` (the organization's voice) or `'followers'` (a member post). The
-- default backfills every existing row as the organization's voice. The service stamps it from the
-- author's role; `feed_posts_social_insert_gate` backs that at the database (a member claim cannot
-- insert 'tenant', a staff claim cannot insert 'followers', a member post has no community) and
-- `feed_posts_visibility_shape_chk` makes "a followers post has no community" a fact of the table.
--
-- SOCIAL-06, D-483, D-484: `feed_posts_social_gate` is RESTRICTIVE, so it ANDs with the tenant
-- isolation and the community gate. A member post is readable only while `social` is on, and only by
-- its author, the author's live followers (`app.social_visible_author_ids()`), the tenant admin and
-- the system lanes. The seam functions are declared by the earlier `*_social_gate_seam.sql` and
-- given their bodies by `*_social_functions.sql`, which is why this file sorts after both. Comments
-- and likes inherit the gate through the inner `exists` of their existing community-gate policies.
--
-- `deleted_by_user_id` is nullable with no foreign key (plan 07 writes it for a moderator removal).
ALTER TABLE "feed_posts" ADD COLUMN "visibility" text DEFAULT 'tenant' NOT NULL;--> statement-breakpoint
ALTER TABLE "feed_posts" ADD COLUMN "deleted_by_user_id" uuid;--> statement-breakpoint
ALTER TABLE "feed_posts" ADD CONSTRAINT "feed_posts_visibility_chk" CHECK ("feed_posts"."visibility" in ('tenant','followers'));--> statement-breakpoint
ALTER TABLE "feed_posts" ADD CONSTRAINT "feed_posts_visibility_shape_chk" CHECK ("feed_posts"."visibility" = 'tenant' or "feed_posts"."community_id" is null);--> statement-breakpoint
CREATE POLICY "feed_posts_social_gate" ON "feed_posts" AS RESTRICTIVE FOR SELECT TO "authenticated" USING (visibility = 'tenant' or ((select app.social_enabled()) and ((select (app.tenant_role() = 'admin_tenant' or app.user_id() = '00000000-0000-0000-0000-000000000000'::uuid)) or author_user_id = any (coalesce((select app.social_visible_author_ids()), '{}'::uuid[])))));--> statement-breakpoint
CREATE POLICY "feed_posts_social_insert_gate" ON "feed_posts" AS RESTRICTIVE FOR INSERT TO "authenticated" WITH CHECK ((app.tenant_role() = 'member' and visibility = 'followers' and community_id is null and (select app.social_enabled())) or (app.tenant_role() <> 'member' and visibility = 'tenant'));